 1| /**
 2|  * Cursor pagination. A cursor is the opaque (base64url) sort key of the last
 3|  * item on the previous page; the next page holds the items whose key is greater.
 4|  * Keys must be unique and totally ordered (e.g. `${createdAt}|${id}`).
 5|  */
 6| import { z } from 'zod';
 7| import { unprocessable } from './problem.ts';
 8| 
 9| export const CursorQuerySchema = z.object({
10|   cursor: z.string().min(1).optional(),
11|   limit: z.coerce.number().int().min(1).max(100).default(20),
12| });
13| export type CursorQuery = z.infer<typeof CursorQuerySchema>;
14| 
15| const CursorPayloadSchema = z.object({ after: z.string() });
16| 
17| export function encodeCursor(key: string): string {
18|   return Buffer.from(JSON.stringify(CursorPayloadSchema.parse({ after: key })), 'utf8').toString('base64url');
19| }
20| 
21| /** Returns the sort key encoded in `cursor`; throws a 422 problem for anything that is not a cursor we issued. */
22| export function decodeCursor(cursor: string): string {
23|   try {
24|     const json: unknown = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
25|     return CursorPayloadSchema.parse(json).after;
26|   } catch {
27|     throw unprocessable('cursor: Invalid cursor', 'invalid-cursor');
28|   }
29| }
30| 
31| /** `{ data: T[], nextCursor: string | null }`: the response schema of every paginated list. */
32| export function pageSchema<T extends z.ZodType>(item: T): z.ZodObject<{ data: z.ZodArray<T>; nextCursor: z.ZodNullable<z.ZodString> }> {
33|   return z.object({ data: z.array(item), nextCursor: z.string().nullable() });
34| }
35| 
36| export function paginate<T>(items: readonly T[], query: CursorQuery, key: (item: T) => string): { data: T[]; nextCursor: string | null } {
37|   const after = query.cursor === undefined ? undefined : decodeCursor(query.cursor);
38|   const sorted = [...items].sort((a, b) => compareKeys(key(a), key(b)));
39|   const remaining = after === undefined ? sorted : sorted.filter((item) => compareKeys(key(item), after) > 0);
40|   const data = remaining.slice(0, query.limit);
41|   const last = data.at(-1);
42|   const nextCursor = remaining.length > data.length && last !== undefined ? encodeCursor(key(last)) : null;
43|   return { data, nextCursor };
44| }
45| 
46| function compareKeys(a: string, b: string): number {
47|   if (a < b) return -1;
48|   return a > b ? 1 : 0;
49| }

problem-json (standards, unit: error paths)
problem-json (unit: error paths)
Every error response is RFC 9457 application/problem+json: { type, title, status, detail, instance }.
Static rules (per src file):
- Never send ad-hoc error bodies (object literals with error / errors / message keys).
- Never res.status(>=400).json/send(...) / sendStatus(>=400) unless the body comes from a problem helper
  (or is a {type,title,status,...} literal sent with .type('application/problem+json')).
  Prefer: throw notFound(detail) / conflict(detail) / new HttpProblem({...}) and let the error middleware send it.
- Every problem producer (new HttpProblem(...), notFound(...), conflict(...), ...) yields type, title, status.
- Handlers never throw / next() a non-problem error (new Error('not found') becomes a 500).
- The app registers an error-handling middleware (err, req, res, next) and a final not-found handler.
Runtime (src/app.ts exports createApp): probes must get Content-Type application/problem+json and a body
with string type/title/detail/instance and integer status equal to the HTTP status:
  GET <base>/__harness_probe__/does-not-exist -> 404; POST/PUT/PATCH malformed JSON -> 400, invalid body -> 422;
  GET/PATCH/DELETE on :param routes with an unknown uuid -> 404 (422 accepted); a route that throws a plain
  Error -> 500 problem without the error message or stack; collection GET -> 200 JSON that is NOT a problem.
  App cannot start -> UNPROVEN.
Passing example:
  usersRouter.get('/v1/users/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const user = store.get(userId);
    if (user === undefined) throw notFound(`user ${userId} not found`);
    res.json(UserSchema.parse(user));
  });
  // app.ts: app.use(notFoundHandler); app.use(errorHandler);  // errorHandler -> sendProblem(res, problem)

rest-conventions (standards, unit: routes)
rest-conventions (unit: routes)
A route passes iff ALL of:
1. Versioned base path: the full path (after app.use prefixes) starts with /v<digits>/.
2. Plural nouns: every static segment after the version is plural (kebab-case: the last word); :params are skipped.
3. Cursor pagination: a GET on a collection path (last segment static) parses req.query with a schema whose
   type has cursor and limit (and no page/offset/skip), and its 2xx response schema has nextCursor and an
   array property data or items.
4. Idempotency: every POST and PATCH has a middleware whose name matches /idempot/i (e.g. idempotency(), per route
   or via router.use(idempotency()) before the route),
   or parses req.headers with a schema that has an 'idempotency-key' property.
5. Status codes: POST on a collection responds res.status(201) (never a bare 200); DELETE responds 204 with
   no body; every literal status is one of 200 201 202 204 304 400 401 403 404 409 412 415 422 428 429 500 503;
   :param routes have a 404 path (throw notFound(...) / HttpProblem 404 / res.status(404)); validation
   failures are 422: a literal 400 in a handler is a violation (400 is only for malformed JSON, in the error middleware).
Passing example:
  usersRouter.get('/v1/users', (req, res) => {
    const query = ListUsersQuerySchema.parse(req.query);      // CursorQuerySchema.extend({...})
    res.json(UserPageSchema.parse(store.list(query)));        // { data: User[], nextCursor: string | null }
  });
  usersRouter.post('/v1/users', idempotency(), (req, res) => {
    const user = store.create(CreateUserSchema.parse(req.body));
    res.status(201).location(`/v1/users/${user.id}`).json(UserSchema.parse(user));
  });
  usersRouter.delete('/v1/users/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    if (!store.remove(userId)) throw notFound(`user ${userId} not found`);
    res.status(204).end();
  });

zod-boundary (standards, unit: handlers)
zod-boundary (unit: route handlers; each hand-written DTO type is one more failing unit)
A route handler passes iff ALL of:
1. Every read of req.params / req.query / req.body / req.headers / req.get() / req.header()
   is the direct argument of <schema>.parse() / .safeParse() / .parseAsync() / .safeParseAsync(),
   where <schema> is a Zod schema (z.any()/z.unknown() validate nothing and do not count).
   IdSchema.parse(req.params.userId) is fine; destructuring or passing `req` along is not.
2. A path with :param segments parses req.params.
3. POST / PUT / PATCH parse req.body.
4. Every 2xx (or unknown-status) body sent with res.json(x) / res.send(x) is <schema>.parse(...)
   or a const initialised with one. res.status(204).end() is fine; non-2xx bodies belong to problem-json.
   `res` is not passed to helpers (problem senders such as sendProblem(res, p) excepted).
Per src file: no `interface` declarations and no `type X = { ... }` object aliases;
use `type X = z.infer<typeof XSchema>`.
Passing example:
  usersRouter.post('/v1/users', idempotency(), (req, res) => {
    const body = CreateUserSchema.parse(req.body);
    const user = store.create(body);
    res.status(201).location(`/v1/users/${user.id}`).json(UserSchema.parse(user));
  });
  usersRouter.get('/v1/users/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const user = store.get(userId);
    if (user === undefined) throw notFound(`user ${userId} not found`);
    res.json(UserSchema.parse(user));
  });
  export type User = z.infer<typeof UserSchema>;

